'use strict';

// Each wet-lab task owns an independent lab schedule.
const TaskLabs = (() => {
  function create(sample = false) {
    return {
      labName: sample ? 'Demo Lab' : '',
      status: sample ? 'Open for experiments' : 'Not configured',
      days: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri'],
      start: '09:00',
      end: '17:00',
      timezone: 'Australia/Sydney',
      note: sample ? 'Please allow 48 hours for experiment scheduling.' : ''
    };
  }

  function copy(value, sample = false) {
    const defaults = create(sample);
    return {
      ...defaults,
      ...value,
      days: [...(Array.isArray(value?.days) ? value.days : defaults.days)]
    };
  }

  function migrate(accounts) {
    let changed = false;
    for (const account of Object.values(accounts)) {
      if (account?.type !== 'wet' || !Array.isArray(account.tasks)) continue;
      const legacy = account.availability;
      for (const task of account.tasks) {
        if (task.availability) continue;
        task.availability = copy(
          legacy ? { ...legacy, labName: legacy.labName || 'Contributor lab' } : undefined,
          task.sample === true
        );
        changed = true;
      }
      if (Object.hasOwn(account, 'availability')) {
        delete account.availability;
        changed = true;
      }
    }
    return changed;
  }

  return { create, copy, migrate };
})();

if (typeof module !== 'undefined') module.exports = TaskLabs;

