let memoryFallback = {};
function readStore() {
  const empty = { accounts: {}, session: null };
  try {
    const current = JSON.parse(localStorage.getItem(STORE));
    if (current) return current;

    const legacy = JSON.parse(localStorage.getItem(LEGACY_STORE));
    if (legacy?.accounts) return legacy;
    if (!legacy?.profiles) return empty;

    const statuses = {
      'Draft · PR pending': 'Awaiting PR',
      'PR submitted': 'Submitted',
      'Under review': 'In review',
      Accepted: 'Accepted',
      Planning: 'Draft',
      'Ready for local run': 'Draft',
      'Evidence packaged': 'Draft',
      'Submitted for review': 'Submitted',
      Published: 'Accepted'
    };
    for (const profile of Object.values(legacy.profiles)) {
      const type = profile?.track;
      if (!['dry', 'wet'].includes(type)) continue;
      const identity = profile.email || 'demo@aisle.local';
      const labNote = [profile.availability, profile.hours, profile.notice].filter(Boolean).join(' · ');
      const tasks = (profile.tasks || []).map(task => ({
        id: task.id,
        title: task.title,
        description: task.description,
        domain: '',
        status: statuses[task.status] || 'Draft',
        sample: Boolean(task.demo),
        created: task.created,
        updated: task.created,
        pr: /^https:\/\/github\.com\/[\w.-]+\/[\w.-]+\/pull\/[1-9]\d*\/?$/.test(task.prUrl) ? task.prUrl : '',
        files: [],
        history: [{ label: `Imported from the previous demo · ${task.status}`, date: task.created }],
        ...(type === 'wet' ? {
          availability: TaskLabs.copy({ labName: profile.name || 'Contributor lab', status: 'By appointment', note: labNote })
        } : {})
      }));
      empty.accounts[`${type}:${identity}`] = { name: profile.name || 'Contributor', identity, type, tasks, notices: [] };
    }
    return empty;
  } catch {
    return memoryFallback.data || empty;
  }
}
let state=readStore();
if(!state.accounts || typeof state.accounts!=='object') state={accounts:{},session:null};
