const drySteps=[['Register your task','Create a Task ID and tell us what scientific capability your experiment will test.'],['Package & verify','Build a Harbor-compatible environment, instructions and verifier. Test locally and retain evaluation logs.'],['Open a pull request','Submit your task through GitHub. Include the Task ID in your PR title and description.'],['Follow the review','Link your PR in your workspace, respond to feedback and track the contribution.']];
const wetSteps=[['Describe your experiment','Register a Task ID, scientific objective and the evidence your lab can provide.'],['Prepare your lab node','Connect an outbound-only local runner with policy checks, a pre-flight simulation and hardware adapters.'],['Run & share evidence','Bundle signed execution traces and readings. Send structured data and raw assets through separate channels.'],['Review & release','Track review, update lab availability and prepare a versioned dataset for the public benchmark.']];
function steps(type){return `<div class="steps">${(type==='dry'?drySteps:wetSteps).map(([title,copy],i)=>`<div class="step"><div class="step-num">0${i+1}</div><h3>${title}</h3><p>${copy}</p></div>`).join('')}</div>`;}
