function wetGuide(){return `<details class="guide-details" open><summary>From cloud intent to local execution</summary><div class="guide-content"><div class="architecture"><div class="arch-node"><div class="eyebrow">01 / Cloud</div><h4>Central benchmark</h4><p>Task definition, high-level goals and typed action primitives with validated parameters.</p></div><div class="arch-node"><div class="eyebrow">02 / Contributor side</div><h4>Local Lab Gateway / Runner</h4><div class="arch-layer"><b>Layer 1</b> · Ingress policy & safety interceptor</div><div class="arch-layer"><b>Layer 2</b> · Virtual shadow & pre-flight dry-run</div><div class="arch-layer"><b>Layer 3</b> · Hardware adapter</div><p>PyLabRobot · ROS · Opentrons API · Serial</p></div><div class="arch-node"><div class="eyebrow">03 / Evidence</div><h4>Observe & attest</h4><p>Local sensors and cameras produce signed execution traces and video feeds for cloud attestation and the leaderboard.</p></div></div><p class="architecture-note">The local runner initiates an outbound-only WebSocket / gRPC connection. No public inbound lab endpoint is required. Cloud agents express intent through typed action primitives; the local runner enforces physical limits, simulates the plan and translates approved actions for the hardware.</p></div></details><details class="guide-details"><summary>How experimental data reaches the benchmark</summary><div class="guide-content"><div class="data-flow"><div class="arch-node"><div class="eyebrow">Contributor</div><h4>Local Lab Node</h4><p>Package raw readings and execution traces after the experiment.</p></div><span class="flow-arrow">↓ &nbsp; Two upload channels &nbsp; ↓</span><div class="fork"><div class="arch-node"><h4>Benchmark API Gateway</h4><p>Structured measurements, task metadata & scoring</p><span class="mono">↓ PostgreSQL · metadata & score records</span></div><div class="arch-node"><h4>S3 / R2 Object Storage</h4><p>Direct upload of large raw assets</p><span class="mono">Videos · microscopy · raw spectra</span></div></div><span class="flow-arrow">↓ &nbsp; Joined by Task ID &nbsp; ↓</span><div class="flow-bottom"><div class="arch-node"><h4>Versioned ETL</h4><p>Clean, de-identify and normalize structured data alongside object assets.</p></div><div class="arch-node"><h4>Hugging Face Datasets</h4><p>Parquet releases, Data Cards and versioned asset references.</p></div><div class="arch-node"><h4>Public leaderboard</h4><p>Reviewed benchmark results on the website or HF Spaces.</p></div></div></div><p class="architecture-note">Proposed data architecture. This demo keeps file metadata locally; it does not connect to laboratory hardware, storage services, databases or a public leaderboard.</p></div></details>`;}
function auth(type){document.title=`${labName(type)} · Sign in · AISLE`;return `${header()}<main id="main" class="fade-in"><section class="auth-section wrap"><a class="back-link" href="#/">${icon('back')} All contribution paths</a><div class="auth-layout"><div class="auth-intro"><div class="eyebrow"><span class="dot"></span> ${labName(type)} contributor</div><h1>Your next<br>contribution<br>starts here.</h1><p>${type==='dry'?'A scientific question. A reproducible environment. A new test of what AI can do.':'A real experiment. A connected laboratory. Evidence that only nature can provide.'}</p><div class="auth-bottom">${icon(type==='dry'?'github':'tasks')}<span>${type==='dry'?'Built with Harbor. Contributed through GitHub.':'Managed in your contributor workspace.'}</span></div></div><div class="auth-box"><div class="tabs" role="tablist" aria-label="Account mode"><button role="tab" aria-selected="${authMode==='signin'}" class="${authMode==='signin'?'active':''}" data-action="auth-mode" data-mode="signin">Sign in</button><button role="tab" aria-selected="${authMode==='signup'}" class="${authMode==='signup'?'active':''}" data-action="auth-mode" data-mode="signup">Sign up</button></div><form id="auth-form" class="form-stack" novalidate>${authMode==='signup'?'<label>Your name<input name="name" placeholder="Your name" autocomplete="name"></label>':''}<label>Email address<input name="email" type="text" inputmode="email" placeholder="you@your-lab.org" autocomplete="username"></label><label>Password<input name="password" type="password" placeholder="Enter any password" autocomplete="off"></label><button class="btn full" type="submit">${authMode==='signup'?'Create your account':'Sign in to your workspace'} ${icon('arrow')}</button></form><div class="demo-hint">${icon('info')}<span>Demo access. Any details work, including blank fields. No authentication or password storage.</span></div><button class="guest-btn" data-action="guest">Just explore the demo →</button></div></div></section><section class="process-section"><div class="wrap"><div class="section-title"><div><div class="eyebrow">The contribution process</div><h2>${type==='dry'?'From a question to a benchmark.':'From your lab to shared evidence.'}</h2></div><p>${type==='dry'?'Register here. Build locally. Collaborate openly.':'You control execution. The benchmark connects the evidence.'}</p></div>${steps(type)}${type==='dry'?dryGuide():wetGuide()}</div></section></main>${footer()}`;}
function newAccount(type,identity,name){const isDry=type==='dry';const id=isDry?'AISLE-DL-0001':'AISLE-WL-0001';return {name:name||'Alex',identity,type,tasks:[{id,title:isDry?'Spectral property prediction':'Closed-loop colour matching',description:isDry?'Evaluate whether an AI scientist can infer spectral properties from a held-out molecular dataset, using a reproducible environment and numerical verifier.':'Evaluate an AI scientist’s ability to choose a formulation, observe measured colour and improve the next experiment using a local liquid-handling setup.',domain:isDry?'Computational chemistry':'Experimental optimisation',status:'Submitted',sample:true,created:'2026-11-06T00:00:00.000Z',updated:'2026-11-06T00:00:00.000Z',pr:'',files:isDry?[]:[{name:'experiment-readings.csv',size:24500},{name:'signed-execution-trace.json',size:18400},{name:'run-observation.mp4',size:12800000}],...(isDry?{}:{availability:TaskLabs.create(true)}),history:[{label:'Task registered',date:'2026-11-06T00:00:00.000Z'},{label:isDry?'Example Harbor package prepared':'Example experiment package attached',date:'2026-11-06T00:10:00.000Z'},{label:'Submission received (demo)',date:'2026-11-06T00:20:00.000Z'}]}],notices:[]};}
