function dashTop(eyebrow,title,subtitle,action=''){return `<div class="dash-top"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
function taskTable(showTools=false){return `<div class="panel"><div class="panel-head"><div><h2>${showTools?'All contributions':'Your contributions'}</h2><p>A home for every scientific question you bring.</p></div>${!showTools?`<a class="text-link" href="#/${route.type}/tasks">View all ${icon('arrow')}</a>`:''}</div>${showTools?`<div class="table-tools"><div class="search-field">${icon('search')}<input id="task-search" aria-label="Search tasks" placeholder="Search tasks or Task ID" value="${esc(taskSearch)}"></div><select id="task-filter" aria-label="Filter task status">${['all','Draft','Awaiting PR','Submitted','Archived'].map(s=>`<option value="${s}" ${s===taskFilter?'selected':''}>${s==='all'?'All active statuses':s}</option>`).join('')}</select></div>`:''}<div id="task-table-content">${taskRows(showTools)}</div></div>`;}
function taskRows(filter=false){let tasks=account().tasks.filter(t=>filter&&taskFilter==='Archived'?t.status==='Archived':t.status!=='Archived');if(filter){tasks=tasks.filter(t=>(taskFilter==='all'||t.status===taskFilter)&&`${t.id} ${t.title} ${t.description} ${t.availability?.labName||''}`.toLowerCase().includes(taskSearch.toLowerCase()));}else tasks=tasks.slice(0,4);if(!tasks.length)return `<div class="empty">${filter?'No tasks match this view. Try another search or status.':'Your next contribution starts with a question. Create a task to begin.'}</div>`;return `<table class="task-table"><thead><tr><th scope="col">Task</th><th scope="col" class="domain-col">${route.type==='wet'?'Lab':'Field'}</th><th scope="col">Status</th><th scope="col" class="date-col">Updated</th><th scope="col"><span class="muted">Action</span></th></tr></thead><tbody>${tasks.map(t=>`<tr><td><button class="task-name" data-action="detail" data-id="${esc(t.id)}">${esc(t.title)}</button><span class="task-id">${esc(t.id)}</span>${t.sample?'<span class="sample-label">DEMO</span>':''}</td><td class="task-domain domain-col">${route.type==='wet'?`<span class="table-lab-name">${esc(t.availability?.labName||'Not assigned')}</span><span class="table-lab-status">${esc(t.availability?.status||'Not configured')}</span>`:esc(t.domain)}</td><td>${badge(t.status)}</td><td class="task-domain date-col">${dateLabel(t.updated)}</td><td><button class="table-action" data-action="detail" data-id="${esc(t.id)}">Manage ↗</button></td></tr>`).join('')}</tbody></table>`;}
function noticesPanel(type){return `<div class="panel"><div class="panel-head"><h2>Notice board</h2><a class="text-link" href="#/${type}/notices">${type==='wet'?'Manage':'View all'} ↗</a></div><div class="panel-body">${account().notices.length?noticeMarkup(account().notices[0],false):`<div class="notice-item"><div class="notice-date">CONTRIBUTOR NOTE · DEMO</div><h3>${type==='dry'?'Keep your Task ID with your PR':'A lab for every task'}</h3><p>${type==='dry'?'Include your Task ID in both the pull request title and description so reviewers can connect the code to your proposal.':'Open Manage on a task to update its laboratory and opening hours. Add a notice when instrument availability or scheduling changes.'}</p></div>`}<div class="notice-item"><div class="notice-date">WORKSPACE UPDATE</div><h3>A sample task is ready to explore</h3><p>Your submitted demo task shows how contributions appear in this workspace. Open Manage to see the submission details.</p></div></div></div>`;}
function overview(type){
 const a=account(),active=a.tasks.filter(t=>t.status!=='Archived'),submitted=active.filter(t=>['Submitted','In review','Accepted'].includes(t.status)).length,pending=active.filter(t=>['Draft','Awaiting PR'].includes(t.status)).length;
 return `${dashTop(`${labName(type)} / Contributor workspace`,`Welcome back, ${esc(a.name)}.`,type==='dry'?'Your ideas, on their way to the benchmark.':'Your experiments, connected to the benchmark.',`<button class="btn" data-action="new-task">${icon('plus')} New task</button>`)}<div class="stat-grid"><div class="stat"><div class="stat-label">Total contributions ${icon('tasks')}</div><div class="stat-number">${String(active.length).padStart(2,'0')}</div><div class="stat-foot">Your registered tasks</div></div><div class="stat"><div class="stat-label">Submitted ${icon('check')}</div><div class="stat-number">${String(submitted).padStart(2,'0')}</div><div class="stat-foot">Includes the sample submission</div></div><div class="stat"><div class="stat-label">${type==='dry'?'Ready for your next step':'Draft tasks'} ${icon('clock')}</div><div class="stat-number">${String(pending).padStart(2,'0')}</div><div class="stat-foot">${type==='dry'?'Drafts & tasks awaiting a PR':'Experiments being prepared'}</div></div></div>${taskTable()}<div class="dashboard-lower"><div class="panel"><div class="panel-head"><h2>Your next contribution</h2><a class="text-link" href="#/${type}/guide">Read guide ↗</a></div><div class="panel-body">${(type==='dry'?drySteps:[['Register your experiment','Create a Task ID and describe the scientific objective.'],['Set up this task’s lab','Open Manage on a task to set its lab name, availability and operating hours. Each task has its own schedule.'],['Share the evidence','Attach readings and execution traces, then submit the experiment package.']]).slice(0,3).map(([title,copy],i)=>`<div class="next-step"><div class="step-circle">${i+1}</div><div><h3>${title}</h3><p>${copy}</p></div></div>`).join('')}</div></div>${noticesPanel(type)}</div>`;
}
function tasksPage(type){return `${dashTop(`${labName(type)} / My tasks`,'Every task. One workspace.','Create, update and follow your contributions.',`<button class="btn" data-action="new-task">${icon('plus')} New task</button>`)}${taskTable(true)}`;}
function taskLabPanel(task){
 const a=task.availability||TaskLabs.create(),configured=a.status!=='Not configured';
 return `<section class="task-lab-panel" aria-label="Task lab availability"><div class="task-lab-heading"><div><h3>Lab availability</h3><p>For this task · <span class="mono">${esc(task.id)}</span></p></div>${task.status==='Archived'?'':`<button class="btn secondary small" data-action="edit-task-lab" data-id="${esc(task.id)}">${configured?'Edit lab availability':'Set up lab'}</button>`}</div><div class="task-lab-identity"><span class="lab-name">${esc(a.labName||'No lab assigned yet')}</span>${badge(a.status)}</div>${configured?`<div class="availability-info"><div>Operating days<b>${a.days.length?a.days.map(esc).join(' · '):'By arrangement'}</b></div><div>Usual hours<b>${esc(a.start)} – ${esc(a.end)}</b></div><div>Time zone<b>${esc(a.timezone)}</b></div></div>${a.note?`<p class="task-lab-note">${esc(a.note)}</p>`:''}`:'<p class="task-lab-note">Add the laboratory and schedule for this experiment. Other tasks keep their own settings.</p>'}</section>`;
}
function taskLabModal(id){
 const task=getTask(id);if(!task||task.status==='Archived'||route.type!=='wet')return;
 const a=task.availability||TaskLabs.create();
 openModal('Lab & availability',`${esc(task.id)} · ${esc(task.title)}`,`<form id="task-lab-form" data-id="${esc(id)}" class="form-stack"><label>Laboratory name<input name="labName" value="${esc(a.labName)}" required maxlength="120" placeholder="e.g. Materials Characterisation Lab"></label><label>Lab status<select name="status" required><option value="" disabled ${a.status==='Not configured'?'selected':''}>Choose availability</option>${['Open for experiments','By appointment','Temporarily unavailable'].map(s=>`<option ${a.status===s?'selected':''}>${s}</option>`).join('')}</select></label><div><label>Operating days</label><div class="days">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(day=>`<button type="button" class="day-btn ${a.days.includes(day)?'selected':''}" data-action="toggle-day" data-day="${day}" aria-pressed="${a.days.includes(day)}">${day}</button>`).join('')}</div></div><div class="two-col"><label>Opens at<input type="time" name="start" required value="${esc(a.start)}"></label><label>Closes at<input type="time" name="end" required value="${esc(a.end)}"></label></div><label>Time zone<select name="timezone">${['Australia/Sydney','Asia/Shanghai','Asia/Singapore','Asia/Tokyo','Europe/London','Europe/Berlin','America/New_York','America/Los_Angeles','UTC'].map(z=>`<option ${a.timezone===z?'selected':''}>${z}</option>`).join('')}</select></label><label>Scheduling note<textarea name="note" placeholder="Access conditions, lead times or instrument availability...">${esc(a.note)}</textarea></label><p class="form-helper">Saved only for this task. Hours use the selected time zone; describe overnight access in the note.</p><div id="availability-error" class="form-error" role="alert"></div><div class="form-actions"><button type="button" class="btn secondary" data-action="detail" data-id="${esc(id)}">Back to task</button><button class="btn" type="submit">Save lab availability ${icon('check')}</button></div></form>`);
}
function noticeMarkup(n,actions=true){return `<article class="notice-item"><div class="notice-date">${esc(n.category)} · ${dateLabel(n.updated)}</div><h3>${esc(n.title)}</h3><p style="white-space:pre-wrap">${esc(n.body)}</p>${actions?`<div class="notice-actions"><button data-action="edit-notice" data-id="${esc(n.id)}">Edit</button><button data-action="remove-notice" data-id="${esc(n.id)}">Remove notice</button></div>`:''}</article>`;}
function noticesPage(type){const own=account().notices;return `${dashTop(`${labName(type)} / Notice board`,'Keep everyone in the loop.',type==='wet'?'Share scheduling updates, instrument changes and lab notices.':'Keep contribution notes and updates alongside your tasks.',`<button class="btn" data-action="new-notice">${icon('plus')} Add notice</button>`)}<div class="notice-editor"><div class="panel"><div class="panel-head"><h2>Your notices <span class="tab-count">${own.length}</span></h2><span class="mono muted" style="font-size:10.5px">LOCAL DEMO</span></div><div class="panel-body">${own.length?own.map(n=>noticeMarkup(n)).join(''):'<div class="empty">No notices yet. Add an update to your workspace.</div>'}</div></div><div class="panel"><div class="panel-head"><h2>From AISLE</h2></div><div class="panel-body"><div class="notice-item"><div class="notice-date">DEMO WORKSPACE · GETTING STARTED</div><h3>${type==='dry'?'Link your Task ID to the contribution':'Keep your schedule current'}</h3><p>${type==='dry'?'After creating a task, copy the PR template from its details panel. Add the Task ID to your PR title and description, then link the PR URL here.':'Before proposing an experiment, open that task’s Manage panel and check its laboratory, operating hours and time zone. Your local runner remains in control of physical execution.'}</p></div></div></div></div>`;}
function guidePage(type){return `${dashTop(`${labName(type)} / Submission guide`,type==='dry'?'Make your science reproducible.':'Let nature verify the result.','A clear path from your first idea to a contribution.',`<button class="btn" data-action="new-task">${icon('plus')} New task</button>`)}<div class="guide-dashboard">${steps(type)}${type==='dry'?dryGuide():wetGuide()}</div>`;}
function openModal(title,subtitle,body,wide=false){lastFocused=document.activeElement;modalRoot.innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><div class="modal-head"><div><div class="eyebrow">${labName(route.type)} / Contributor workspace</div><h2 id="modal-title">${title}</h2><p>${subtitle}</p></div><button class="close-btn" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div></section></div>`;document.body.classList.add('modal-open');requestAnimationFrame(()=>modalRoot.querySelector('input:not([type="hidden"]),textarea,button')?.focus());}
function closeModal(){modalRoot.innerHTML='';document.body.classList.remove('modal-open');selectedFiles=[];activeTaskId=null;if(lastFocused?.isConnected)lastFocused.focus();}
function newTaskModal(){openModal('Start with a scientific question.','Create your Task ID first. It will stay with your contribution from here on.',`<form id="create-task-form" class="form-stack"><label>Task ID<div class="id-field"><input name="taskId" value="${nextId()}" maxlength="64" required title="Use 3–64 letters, numbers, hyphens or underscores."><button type="button" class="btn secondary small" data-action="generate-id">Generate ID</button></div></label><label>Task title<input name="title" required maxlength="100" placeholder="e.g. ${route.type==='dry'?'Predict molecular spectral properties':'Closed-loop formulation optimisation'}"></label><label>Scientific objective<textarea name="description" required maxlength="2000" placeholder="What should the AI scientist do, and how will you know it succeeded?"></textarea></label><label>Research field<select name="domain">${(route.type==='dry'?['Computational chemistry','Bioinformatics','Materials science','Scientific reasoning','Other']:['Experimental optimisation','Liquid handling','Materials characterisation','Spectroscopy','Other']).map(x=>`<option>${x}</option>`).join('')}</select></label><div class="form-helper">${route.type==='dry'?'Next: prepare your Harbor task and use this Task ID in your GitHub pull request.':'Next: attach experimental readings, execution traces and supporting evidence.'}</div><div id="create-error" class="form-error" role="alert"></div><div class="form-actions"><button class="btn secondary" type="button" data-action="close-modal">Cancel</button><button class="btn" type="submit">Create task ${icon('arrow')}</button></div></form>`);}
function createTask(form){const f=new FormData(form);const id=f.get('taskId').trim(),title=f.get('title').trim(),description=f.get('description').trim();const error=document.getElementById('create-error');if(!/^[A-Za-z0-9][A-Za-z0-9_-]{2,63}$/.test(id)||!title||!description){error.textContent='Add a valid Task ID, a title and a short scientific objective.';return;}if(account().tasks.some(t=>t.id.toLowerCase()===id.toLowerCase())){error.textContent='That Task ID is already in your workspace. Please choose another.';return;}const now=today();const task={id,title,description,domain:f.get('domain'),status:route.type==='dry'?'Awaiting PR':'Draft',sample:false,created:now,updated:now,pr:'',files:[],...(route.type==='wet'?{availability:TaskLabs.create()}:{}),history:[{label:'Task registered',date:now}]};account().tasks.unshift(task);save();render(false);detailModal(id,true);toast('Task created. Your next step is ready.');}
function prTemplate(t){return `## Task ID\n${t.id}\n\n## Scientific objective\n${t.description}\n\n## Reproducibility\n- [ ] Harbor-compatible task package\n- [ ] Environment and dependencies documented\n- [ ] Verifier and scoring method included\n- [ ] Reference-solution results (where applicable)\n- [ ] Evaluation settings and execution logs\n\n## Validation\nDescribe your local test results and any known limitations.\n`;}
function detailModal(id,created=false){const t=getTask(id);if(!t)return;activeTaskId=id;const wet=route.type==='wet';openModal(esc(t.title),`Task ID · ${esc(t.id)}`,`${created?`<div class="success-heading">${icon('check')}<div><h3>Your task is registered.</h3><p>${wet?'Next, add the experiment package below.':'Next, include your Task ID in a GitHub pull request.'}</p></div></div>`:''}<div class="detail-meta">${badge(t.status)}<span class="mono muted" style="font-size:11.5px">${esc(t.domain)}</span>${t.sample?'<span class="sample-label">ILLUSTRATIVE DEMO TASK</span>':''}</div><p class="detail-desc">${esc(t.description)}</p>${wet?taskLabPanel(t):''}${t.status==='Archived'?'<div class="notice-banner">This task is archived. Restore it to continue managing the submission.</div>':wet?wetTaskDetails(t):dryTaskDetails(t)}<h3 class="detail-section-title">Contribution history</h3><div class="timeline">${t.history.map(h=>`<div class="timeline-item"><i></i><div><strong>${esc(h.label)}</strong><p>${dateLabel(h.date)}</p></div></div>`).join('')}</div><div class="delete-actions">${t.status==='Archived'?`<button class="btn small" data-action="restore-task" data-id="${esc(t.id)}">Restore task</button>`:`<button class="danger-link" data-action="archive-task" data-id="${esc(t.id)}">Archive task</button><button class="btn secondary small" data-action="edit-task" data-id="${esc(t.id)}">Edit task details</button>`}</div>`,true);activeTaskId=id;}
function dryTaskDetails(t){return `<h3 class="detail-section-title">1. Prepare your Harbor task</h3><p class="form-helper">Package the instructions, task configuration, environment and verifier. Run your local checks and retain the evaluation logs.</p><h3 class="detail-section-title">2. Open your pull request</h3><div class="copy-line"><p>PR title: <span class="blue">[${esc(t.id)}] ${esc(t.title)}</span></p><button class="btn secondary small" data-action="copy-title" data-id="${esc(t.id)}">Copy title</button></div><pre class="code-block">${esc(prTemplate(t))}</pre><div class="detail-actions"><button class="btn secondary small" data-action="copy-pr" data-id="${esc(t.id)}">Copy PR template</button><button class="btn secondary small" data-action="download-pr" data-id="${esc(t.id)}">${icon('download')} Download .md</button><a class="btn small" href="${REPO}/compare" target="_blank" rel="noopener">Open GitHub ${icon('external')}</a></div><h3 class="detail-section-title">3. Link your PR to this task</h3>${t.sample?'<p class="form-helper" style="margin-bottom:12px">This sample is marked Submitted for demonstration. No real pull request was created.</p>':''}${t.pr?`<p class="form-helper" style="margin-bottom:12px"><a class="blue" href="${esc(t.pr)}" target="_blank" rel="noopener">View linked pull request ↗</a></p>`:''}<form id="pr-link-form" data-id="${esc(t.id)}"><div class="inline-link-form"><input name="pr" aria-label="GitHub pull request URL" type="url" required placeholder="https://github.com/owner/repo/pull/123" value="${esc(t.pr)}"><button class="btn small" type="submit">${t.pr?'Update PR':'Link PR'}</button></div><div id="pr-error" class="form-error" role="alert"></div></form><p class="form-helper">Linking updates this demo’s status to Submitted. GitHub review is not connected.</p>`;}
function fileSize(bytes){return bytes>=1e6?`${(bytes/1e6).toFixed(1)} MB`:bytes>=1e3?`${(bytes/1e3).toFixed(1)} KB`:`${bytes} B`;}
function fileEntries(files){return files.map(f=>`<div class="file-entry"><span>${esc(f.name)}</span><span style="flex-shrink:0">${fileSize(f.size)}</span></div>`).join('');}
function wetTaskDetails(t){return `<h3 class="detail-section-title">Experimental evidence</h3><p class="form-helper" style="margin-bottom:15px">Attach structured readings and operation traces, with raw video, microscopy or spectra where relevant. All evidence stays associated with <span class="blue">${esc(t.id)}</span>.</p>${t.files.length?`<div class="file-list">${fileEntries(t.files)}</div><p class="form-helper">${t.sample?'Example package · no files uploaded':'Saved file metadata · file contents are not stored'}</p>`:''}<form id="wet-submit-form" data-id="${esc(t.id)}" style="margin-top:20px"><label class="upload-zone">${icon('upload')}<p>Choose your experiment files</p><small>CSV, JSON, archives, images, spectra or video<br>Demo only: names and sizes are recorded; no bytes are uploaded.</small><input id="evidence-files" type="file" multiple aria-label="Choose experiment evidence files"></label><div id="selected-files" class="file-list"></div><div class="detail-actions"><button class="btn secondary small" type="button" data-action="sample-package">Use demo package</button></div><label class="check-line"><input type="checkbox" name="reviewed" required><span>I have reviewed the package description and confirm it is ready for this demo submission.</span></label><div id="wet-error" class="form-error" role="alert"></div><div class="form-actions"><button class="btn secondary" type="button" data-action="save-evidence" data-id="${esc(t.id)}">Save evidence draft</button><button class="btn" type="submit">${t.status==='Submitted'?'Update submission':'Submit experiment'} ${icon('arrow')}</button></div></form>`;}
function editTaskModal(id){const t=getTask(id);openModal('Refine your task.','The Task ID stays fixed so all evidence and review remain connected.',`<form id="edit-task-form" data-id="${esc(id)}" class="form-stack"><label>Task ID<input value="${esc(id)}" disabled></label><label>Task title<input name="title" value="${esc(t.title)}" required maxlength="100"></label><label>Scientific objective<textarea name="description" required maxlength="2000">${esc(t.description)}</textarea></label><label>Research field<input name="domain" value="${esc(t.domain)}" required maxlength="80"></label><div id="edit-error" class="form-error" role="alert"></div><div class="form-actions"><button type="button" class="btn secondary" data-action="detail" data-id="${esc(id)}">Back to task</button><button type="submit" class="btn">Save changes ${icon('check')}</button></div></form>`);}
function noticeModal(id=null){const n=account().notices.find(n=>n.id===id);openModal(n?'Update your notice.':'A note for your workspace.',route.type==='wet'?'Share lab availability, instrument changes or scheduling information.':'Keep an update alongside your contributions.',`<form id="notice-form" data-id="${n?esc(n.id):''}" class="form-stack"><label>Notice title<input name="title" value="${esc(n?.title||'')}" required maxlength="120" placeholder="e.g. Instrument maintenance next week"></label><label>Category<select name="category">${['Lab availability','Instrument update','Scheduling','Contribution update','General'].map(c=>`<option ${n?.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Message<textarea name="body" required maxlength="2000" placeholder="What should contributors know?">${esc(n?.body||'')}</textarea></label><p class="form-helper">Notices are saved in this browser’s demo workspace. Nothing is sent or published externally.</p><div id="notice-error" class="form-error" role="alert"></div><div class="form-actions"><button type="button" class="btn secondary" data-action="close-modal">Cancel</button><button type="submit" class="btn">${n?'Save changes':'Add notice'} ${icon('check')}</button></div></form>`);}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4000);}
async function copyText(textValue){try{await navigator.clipboard.writeText(textValue);toast('Copied to clipboard.');}catch{const area=document.createElement('textarea');area.value=textValue;area.style.position='fixed';area.style.opacity='0';document.body.append(area);area.select();const ok=document.execCommand('copy');area.remove();toast(ok?'Copied to clipboard.':'Clipboard unavailable. Use the download button.');}}
function download(name,content,type='text/markdown'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function updateHistory(task,label){task.updated=today();task.history.push({label,date:task.updated});}
function mergeEvidence(task){const files=new Map(task.files.map(f=>[f.name,f]));selectedFiles.forEach(f=>files.set(f.name,f));task.files=[...files.values()];}
function render(resetScroll=true){const parts=location.hash.replace(/^#\/?/,'').split('/').filter(Boolean);const type=parts[0]==='wet'?'wet':'dry';const view=parts[0]&&['dry','wet'].includes(parts[0])?(parts[1] === 'auth' ? 'login' : parts[1] || 'login'):'home';const known=['home','login','dashboard','tasks','availability','notices','guide'];route={type,view:known.includes(view)?view:'home'};if(route.view==='availability'){location.replace(`#/${type}/tasks`);return;}if(!['home','login'].includes(route.view)&&(!account()||state.session.type!==type)){location.replace(`#/${type}/login`);return;}closeModal();app.innerHTML=route.view==='home'?home():route.view==='login'?auth(type):workspace(type,route.view);if(resetScroll)window.scrollTo({top:0,behavior:'instant'});}
document.addEventListener('click',event=>{
 const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;const id=el.dataset.id;
 if(action==='skip'){event.preventDefault();const main=document.getElementById('main');main.setAttribute('tabindex','-1');main.focus();}
 else if(action==='menu'){const nav=document.getElementById('main-nav');nav.classList.toggle('open');el.setAttribute('aria-expanded',String(nav.classList.contains('open')));el.textContent=nav.classList.contains('open')?'Close −':'Menu +';}
 else if(action==='scroll')document.getElementById(el.dataset.target)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
 else if(action==='auth-mode'){const currentEmail=document.querySelector('#auth-form [name="email"]')?.value||'';const currentName=document.querySelector('#auth-form [name="name"]')?.value||'';authMode=el.dataset.mode;render(false);document.querySelector('#auth-form [name="email"]').value=currentEmail;if(currentName&&document.querySelector('#auth-form [name="name"]'))document.querySelector('#auth-form [name="name"]').value=currentName;document.querySelector(`[data-mode="${authMode}"]`)?.focus();}
 else if(action==='guest')signIn(null);
 else if(action==='signout'){state.session=null;save();location.hash=`#/${route.type}/login`;toast('Signed out. Your demo tasks are saved in this browser.');}
 else if(action==='new-task')newTaskModal();
 else if(action==='generate-id'){const input=document.querySelector('#create-task-form [name="taskId"]');input.value=nextId();input.focus();}
 else if(action==='close-modal')closeModal();
 else if(action==='detail')detailModal(id);
 else if(action==='edit-task')editTaskModal(id);
 else if(action==='copy-pr')copyText(prTemplate(getTask(id)));
 else if(action==='copy-title'){const t=getTask(id);copyText(`[${t.id}] ${t.title}`);}
 else if(action==='download-pr')download(`${id}-pull-request.md`,prTemplate(getTask(id)));
 else if(action==='archive-task'){const t=getTask(id);t.previousStatus=t.status;t.status='Archived';updateHistory(t,'Task archived');save();render(false);toast('Task archived. Restore it from My tasks → Archived.');}
 else if(action==='restore-task'){const t=getTask(id);t.status=t.previousStatus||'Draft';updateHistory(t,'Task restored');save();render(false);detailModal(id);toast('Task restored.');}
 else if(action==='sample-package'){selectedFiles=[{name:'experiment-readings.csv',size:24500},{name:'signed-execution-trace.json',size:18400},{name:'run-observation.mp4',size:12800000}];document.getElementById('selected-files').innerHTML=fileEntries(selectedFiles);toast('Example file metadata added. No files will be uploaded.');}
 else if(action==='save-evidence'){const t=getTask(id);if(!selectedFiles.length){document.getElementById('wet-error').textContent='Choose files or use the demo package first.';return;}mergeEvidence(t);updateHistory(t,'Evidence draft saved (metadata only)');save();render(false);detailModal(id);toast('Evidence draft saved.');}
 else if(action==='toggle-day'){el.classList.toggle('selected');el.setAttribute('aria-pressed',String(el.classList.contains('selected')));}
 else if(action==='edit-task-lab')taskLabModal(id);
 else if(action==='new-notice')noticeModal();
 else if(action==='edit-notice')noticeModal(id);
 else if(action==='remove-notice'){account().notices=account().notices.filter(n=>n.id!==id);save();render(false);toast('Notice removed from this demo workspace.');}
});
document.addEventListener('submit',event=>{
 const form=event.target;if(!(form instanceof HTMLFormElement))return;
 if(!['auth-form','create-task-form','edit-task-form','pr-link-form','wet-submit-form','task-lab-form','notice-form'].includes(form.id))return;
 event.preventDefault();
 if(form.id==='auth-form'){signIn(form);return;}
 if(form.id==='create-task-form'){createTask(form);return;}
 const f=new FormData(form);
 if(form.id==='edit-task-form'){const t=getTask(form.dataset.id);if(!f.get('title').trim()||!f.get('description').trim()||!f.get('domain').trim()){document.getElementById('edit-error').textContent='Please complete each field.';return;}t.title=f.get('title').trim();t.description=f.get('description').trim();t.domain=f.get('domain').trim();updateHistory(t,'Task details updated');save();render(false);detailModal(t.id);toast('Task details updated.');}
 else if(form.id==='pr-link-form'){const t=getTask(form.dataset.id),url=f.get('pr').trim();if(!/^https:\/\/github\.com\/[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+\/pull\/[1-9]\d*\/?$/.test(url)){document.getElementById('pr-error').textContent='Use a GitHub pull request URL such as https://github.com/owner/repo/pull/123.';return;}t.pr=url;t.status='Submitted';t.sample=false;updateHistory(t,'Pull request linked · submission received (demo)');save();render(false);detailModal(t.id);toast('PR linked. Task marked Submitted in this demo.');}
 else if(form.id==='wet-submit-form'){const t=getTask(form.dataset.id);if(!selectedFiles.length&&!t.files.length){document.getElementById('wet-error').textContent='Choose evidence files or use the demo package before submitting.';return;}mergeEvidence(t);const wasSubmitted=t.status==='Submitted';t.status='Submitted';t.sample=false;updateHistory(t,wasSubmitted?'Submission updated (demo)':'Experiment submitted successfully (demo)');save();render(false);detailModal(t.id);toast(wasSubmitted?'Submission updated. No files were uploaded.':'Experiment submitted successfully in this demo.');}
 else if(form.id==='task-lab-form'){
  const task=getTask(form.dataset.id);if(!task||task.status==='Archived'||route.type!=='wet')return;
  const error=document.getElementById('availability-error');
  if(!f.get('labName').trim()){error.textContent='Add the name of the laboratory for this task.';return;}
  if(f.get('start')>=f.get('end')){error.textContent='Closing time must be after opening time. Describe overnight access in the note.';return;}
  const days=[...form.querySelectorAll('.day-btn.selected')].map(el=>el.dataset.day);
  if(f.get('status')==='Open for experiments'&&!days.length){error.textContent='Choose at least one operating day, or select By appointment.';return;}
  task.availability=TaskLabs.copy({labName:f.get('labName').trim(),status:f.get('status'),start:f.get('start'),end:f.get('end'),timezone:f.get('timezone'),note:f.get('note').trim(),days});
  updateHistory(task,'Lab availability updated');save();render(false);detailModal(task.id);toast(`Lab availability saved for ${task.id}.`);
 }
 else if(form.id==='notice-form'){if(!f.get('title').trim()||!f.get('body').trim()){document.getElementById('notice-error').textContent='Add a title and message for your notice.';return;}const existing=account().notices.find(n=>n.id===form.dataset.id);const n={id:existing?.id||`notice-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,title:f.get('title').trim(),body:f.get('body').trim(),category:f.get('category'),updated:today()};if(existing)Object.assign(existing,n);else account().notices.unshift(n);save();render(false);toast('Notice saved to your demo workspace.');}
});
document.addEventListener('input',event=>{if(event.target.id==='task-search'){taskSearch=event.target.value;document.getElementById('task-table-content').innerHTML=taskRows(true);}});
document.addEventListener('change',event=>{if(event.target.id==='task-filter'){taskFilter=event.target.value;document.getElementById('task-table-content').innerHTML=taskRows(true);}else if(event.target.id==='evidence-files'){selectedFiles=[...event.target.files].map(({name,size})=>({name,size}));document.getElementById('selected-files').innerHTML=fileEntries(selectedFiles);}});
document.addEventListener('keydown',event=>{const dialog=modalRoot.querySelector('[role="dialog"]');if(!dialog)return;if(event.key==='Escape'){closeModal();return;}if(event.key==='Tab'){const focusables=[...dialog.querySelectorAll('a[href],button:not(:disabled),input:not(:disabled),textarea,select,[tabindex="0"]')].filter(el=>el.offsetParent!==null);const first=focusables[0],last=focusables.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
window.addEventListener('hashchange',()=>{taskSearch='';taskFilter='all';render();});
if(TaskLabs.migrate(state.accounts))save();
render();
